types:
TYPE ST_Recipe :
STRUCT
    recipeID : INT;
    totalRatio : REAL;
    temperature : REAL;
END_STRUCT
END_TYPE

declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    recipe : ARRAY[1..8] OF ST_Recipe;
    selSlot : INT;
    loadCmd : BOOL;
    running : BOOL;
END_VAR
VAR_OUTPUT
    valid : BOOL;
    loadedID : INT;
END_VAR
VAR
    prevLoadCmd  : BOOL;
    prevValid    : BOOL;
    prevLoadedID : INT;
    edge         : BOOL;
    slotIndex    : INT;
    slotRecipe   : ST_Recipe;
    ratioOK      : BOOL;
    tempOK       : BOOL;
END_VAR

implementation:
edge := loadCmd AND NOT prevLoadCmd;

    IF running THEN

        valid := prevValid;
        loadedID := prevLoadedID;
    ELSIF edge THEN

        IF (selSlot < 1) OR (selSlot > 8) THEN

            valid := FALSE;
            loadedID := 0;
        ELSE
            slotIndex := selSlot;
            slotRecipe := recipe[slotIndex];

            IF slotRecipe.recipeID = 0 THEN

                valid := FALSE;
                loadedID := 0;
            ELSE
                ratioOK := (slotRecipe.totalRatio >= 99.0) AND (slotRecipe.totalRatio <= 101.0);
                tempOK  := (slotRecipe.temperature >= 30.0) AND (slotRecipe.temperature <= 180.0);

                IF ratioOK AND tempOK THEN
                    valid := TRUE;
                    loadedID := slotRecipe.recipeID;
                ELSE
                    valid := FALSE;
                    loadedID := 0;
                END_IF;
            END_IF;
        END_IF;
    ELSE

        valid := prevValid;
        loadedID := prevLoadedID;
    END_IF;


    prevLoadCmd  := loadCmd;
    prevValid    := valid;
    prevLoadedID := loadedID;
